"use client"

import { useEffect, useRef } from "react"

import "./tybow-motion.css"

import { FlushPhoto } from "@/components/tybow/flush-photo"
import { cn } from "@/lib/utils"

export type CollectionStoryCard = {
  title: string
  line?: string
  photo?: { src?: string; alt: string }
}

export type CollectionStoryProps = {
  id?: string
  eyebrow?: string
  title: string
  copy: string
  cards?: CollectionStoryCard[]
  photo?: { src?: string; alt: string }
  collage?: { src?: string; alt: string }[]
  primaryCta?: { href: string; label: string }
  secondaryCta?: { href: string; label: string }
}

export function CollectionStory({
  id,
  eyebrow,
  title,
  copy,
  cards,
  photo,
  collage,
}: CollectionStoryProps) {
  const rail: CollectionStoryCard[] =
    cards ??
    (collage ?? (photo ? [photo] : [])).map((item) => ({
      title: item.alt,
      photo: item,
    }))
  const deckRef = useRef<HTMLElement>(null)
  const trackRef = useRef<HTMLDivElement>(null)
  const viewportRef = useRef<HTMLDivElement>(null)
  const barRef = useRef<HTMLSpanElement>(null)

  useEffect(() => {
    const deckEl = deckRef.current
    const trackEl = trackRef.current
    const viewportEl = viewportRef.current
    const bar = barRef.current
    if (!deckEl || !trackEl || !viewportEl || rail.length < 2) return
    const deck = deckEl
    const track = trackEl
    const viewport = viewportEl

    const mq = window.matchMedia("(min-width: 960px)")
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)")
    let wired = false
    let ticking = false
    let maxX = 0

    const cardEls = () =>
      Array.from(deck.querySelectorAll<HTMLElement>("[data-tybow-card]"))

    function setActive(idx: number) {
      cardEls().forEach((card, i) => {
        card.classList.toggle("is-active", i === idx)
      })
    }

    function teardown() {
      deck.style.height = ""
      track.style.transform = ""
      if (bar) bar.style.transform = ""
      cardEls().forEach((card) => card.classList.add("is-active"))
    }

    function measure() {
      maxX = Math.max(0, track.scrollWidth - (viewport.clientWidth || 1))
      const vh = window.innerHeight || 800
      const byCards = Math.max(0, rail.length - 1) * vh * 0.75
      const byTrack = maxX * 0.9
      let travel = Math.max(byCards, byTrack)
      if (travel < vh * 1.1) travel = vh * 1.1
      deck.style.height = `${Math.round(vh + travel)}px`
    }

    function apply(p: number) {
      const travel = Math.max(0, Math.min(1, (p - 0.06) / 0.94))
      track.style.transform = `translate3d(${(-(travel * maxX)).toFixed(2)}px,0,0)`
      if (bar) bar.style.transform = `scaleX(${travel.toFixed(4)})`

      const viewportBox = viewport.getBoundingClientRect()
      const visibleLeft = Math.max(0, viewportBox.left)
      const visibleRight = Math.min(window.innerWidth, viewportBox.right)
      const mid = visibleLeft + Math.max(0, visibleRight - visibleLeft) / 2
      let best = 0
      let bestDist = Infinity
      cardEls().forEach((card, i) => {
        const box = card.getBoundingClientRect()
        const d = Math.abs(box.left + box.width / 2 - mid)
        if (d < bestDist) {
          bestDist = d
          best = i
        }
      })
      setActive(best)
    }

    function progress() {
      const range = deck.offsetHeight - window.innerHeight
      const p = range < 1 ? 0 : -deck.getBoundingClientRect().top / range
      return p < 0 ? 0 : p > 1 ? 1 : p
    }

    function sync() {
      ticking = false
      apply(progress())
    }

    function onScroll() {
      if (ticking) return
      ticking = true
      requestAnimationFrame(sync)
    }

    function activate() {
      if (!mq.matches || reduced.matches) {
        if (wired) {
          window.removeEventListener("scroll", onScroll)
          wired = false
        }
        teardown()
        return
      }
      measure()
      sync()
      if (!wired) {
        window.addEventListener("scroll", onScroll, { passive: true })
        wired = true
      }
    }

    activate()
    window.addEventListener("resize", activate, { passive: true })
    window.addEventListener("load", activate)
    mq.addEventListener?.("change", activate)
    return () => {
      window.removeEventListener("scroll", onScroll)
      window.removeEventListener("resize", activate)
      window.removeEventListener("load", activate)
      teardown()
    }
  }, [rail.length])

  return (
    <section ref={deckRef} id={id} className="relative z-[3] bg-background">
      <div className="flex min-h-0 flex-col max-[959px]:static max-[959px]:h-auto max-[959px]:overflow-visible min-[960px]:sticky min-[960px]:top-0 min-[960px]:h-svh min-[960px]:overflow-hidden">
        <div className="flex h-full w-full flex-col gap-[clamp(1.1rem,2.2vh,1.75rem)] pt-[clamp(3.5rem,8vw,5.75rem)] pb-[clamp(3.5rem,8vw,5.75rem)] min-[960px]:pt-[clamp(5.25rem,9vh,6.75rem)] min-[960px]:pb-[clamp(1.5rem,3.5vh,2.5rem)]">
          <div className="max-w-[44rem] px-[7vw]">
            {eyebrow ? (
              <p className="text-[0.7rem] font-medium tracking-[0.26em] text-primary uppercase">
                {eyebrow}
              </p>
            ) : null}
            <h2 className="mt-3 font-display text-[length:clamp(1.85rem,3.2vw,3rem)] font-light tracking-[0.055em] text-foreground uppercase">
              {title}
            </h2>
            <p className="mt-4 max-w-[38rem] text-pretty text-foreground">{copy}</p>
            <div className="mt-3 hidden max-w-[11rem] min-[960px]:flex">
              <div className="relative h-px flex-1 overflow-hidden bg-foreground/20">
                <span
                  ref={barRef}
                  className="absolute inset-0 origin-left bg-primary"
                  style={{ transform: "scaleX(0)" }}
                />
              </div>
            </div>
          </div>
          <div
            ref={viewportRef}
            className="min-w-0 overflow-x-auto overflow-y-hidden pr-0 pl-[7vw] max-[959px]:snap-x max-[959px]:snap-mandatory min-[960px]:w-0 min-[960px]:min-w-full min-[960px]:flex-1 min-[960px]:overflow-hidden"
          >
            <div
              ref={trackRef}
              className="tybow-deck-track flex h-[min(64vw,32rem)] gap-[clamp(14px,1.6vw,26px)] will-change-transform min-[960px]:h-full"
            >
              {rail.map((card, index) => (
                <article
                  key={card.title}
                  data-tybow-card
                  className={cn(
                    "tybow-deck-card relative h-full w-[min(86vw,420px)] shrink-0 overflow-hidden bg-muted max-[959px]:h-[min(64vw,520px)] max-[959px]:snap-start min-[960px]:w-[clamp(720px,82vw,1120px)]",
                    index === 0 && "is-active",
                  )}
                >
                  {card.photo ? (
                    <FlushPhoto
                      src={card.photo.src}
                      alt={card.photo.alt}
                      className="absolute inset-0 size-full"
                    />
                  ) : null}
                  <div
                    className="absolute inset-0 bg-[linear-gradient(180deg,transparent_38%,color-mix(in_oklch,var(--foreground)_68%,transparent)_72%,color-mix(in_oklch,var(--foreground)_96%,transparent)_100%),color-mix(in_oklch,var(--foreground)_26%,transparent)]"
                    aria-hidden="true"
                  />
                  <div className="tybow-deck-card-body absolute inset-x-0 bottom-[clamp(1.5rem,4vh,2.75rem)] z-[2] px-[clamp(1rem,2vw,1.75rem)] text-center text-primary-foreground">
                    <h3 className="font-display text-[length:clamp(1.6rem,2.5vw,2.75rem)] font-light tracking-[0.045em] uppercase">
                      {card.title}
                    </h3>
                    {card.line ? (
                      <p className="mt-3 text-[0.66rem] font-medium tracking-[0.2em] text-primary-foreground/80 uppercase">
                        {card.line}
                      </p>
                    ) : null}
                  </div>
                </article>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}

import { cn } from "@/lib/utils"

export type FlushPhotoProps = {
  src?: string
  alt: string
  label?: string
  fit?: "cover" | "contain"
  className?: string
}

export type MediaFrame = { src?: string; alt: string }

export function MediaStack({
  frames,
  on,
  slideClassName,
  className,
  objectPosition,
}: {
  frames: MediaFrame[]
  on: number
  slideClassName: string
  className?: string
  objectPosition?: string
}) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {frames.map((frame, index) =>
        frame.src ? (
          // Parent owns crop. Animation classes must land on the img.
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={`${frame.src}-${index}`}
            src={frame.src}
            alt={index === on ? frame.alt : ""}
            decoding="async"
            className={cn(slideClassName, index === on && "is-on")}
            style={objectPosition ? { objectPosition } : undefined}
          />
        ) : (
          <div
            key={`${frame.alt}-${index}`}
            className={cn(
              slideClassName,
              index === on && "is-on",
              "flex items-center justify-center bg-muted",
            )}
            role="img"
            aria-label={frame.alt}
          />
        ),
      )}
    </div>
  )
}

export function FlushPhoto({
  src,
  alt,
  label = "replace with client photo",
  fit = "cover",
  className,
}: FlushPhotoProps) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {src ? (
        // Parent owns crop and radius. No inner mat.
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={src}
          alt={alt}
          className={cn(
            "absolute inset-0 size-full",
            fit === "contain" ? "object-contain" : "object-cover",
          )}
        />
      ) : (
        <div
          className="absolute inset-0 flex items-center justify-center bg-muted px-6 text-center"
          role="img"
          aria-label={alt}
        >
          <p className="text-sm text-muted-foreground">{label}</p>
        </div>
      )}
    </div>
  )
}

/* Motion ported from The Pines: wh-pines.css + wh-pe-brand.css.
   Token-only. Values (timings, easings, travel) stay literal. */

@keyframes tybow-pull {
  to {
    transform: none;
    opacity: 1;
  }
}

.tybow-pull {
  display: inline-block;
  transform: translateY(0.42em);
  opacity: 0;
  animation: tybow-pull 0.72s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  animation-delay: calc(var(--i, 0) * 90ms + 80ms);
}

.tybow-pull-late {
  transform: translateY(0.8rem);
  opacity: 0;
  animation: tybow-pull 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Ken Burns lives on the IMG, not a wrapper. */
.tybow-hero-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  object-position: 50% 52%;
  opacity: 0;
  transform: scale(1.02);
  transition:
    opacity 1.1s cubic-bezier(0.22, 1, 0.36, 1),
    transform 7s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}

.tybow-hero-slide.is-on {
  opacity: 1;
  transform: scale(1);
}

.tybow-look-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-look-slide.is-on {
  opacity: 1;
}

.tybow-overview-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-overview-slide.is-on {
  opacity: 1;
  z-index: 1;
}

.tybow-gallery {
  display: flex;
  flex-direction: row;
  gap: 1px;
  width: 100%;
  height: min(56vh, 32rem);
  min-height: 22rem;
  overflow: hidden;
  background: var(--foreground);
}

.tybow-gallery-item {
  position: relative;
  overflow: hidden;
  flex: 0.5 1 2.55rem;
  min-width: 2.45rem;
  height: 100%;
  padding: 0;
  border: 0;
  background: var(--foreground);
  cursor: pointer;
  text-align: left;
  line-height: 0;
  transition: flex-grow 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-gallery-item.is-active {
  flex-grow: 16;
}

.tybow-gallery-item img,
.tybow-gallery-item .tybow-gallery-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 48%;
}

.tybow-gallery-item::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    to right,
    color-mix(in oklch, var(--foreground) 88%, transparent) 0%,
    color-mix(in oklch, var(--foreground) 62%, transparent) 55%,
    color-mix(in oklch, var(--foreground) 28%, transparent) 100%
  );
  opacity: 1;
  transition: opacity 0.3s ease;
}

.tybow-gallery-item.is-active::after {
  opacity: 0;
}

.tybow-gallery-spine {
  position: absolute;
  inset: 0 auto 0 0;
  z-index: 1;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  padding: 1.05rem 0.55rem;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--primary-foreground);
  text-shadow: 0 1px 12px color-mix(in oklch, var(--foreground) 70%, transparent);
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.25s ease;
}

.tybow-gallery-item.is-active .tybow-gallery-spine {
  opacity: 0;
}

.tybow-gallery-cap {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  padding: 2.6rem 1.2rem 1.05rem;
  background: linear-gradient(
    to top,
    color-mix(in oklch, var(--foreground) 70%, transparent),
    transparent
  );
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--primary-foreground);
  pointer-events: none;
  opacity: 0;
  transform: translateY(0.5rem);
  transition:
    opacity 0.3s ease,
    transform 0.3s ease;
}

.tybow-gallery-item.is-active .tybow-gallery-cap {
  opacity: 1;
  transform: none;
}

.tybow-deck-card-body,
.tybow-deck-card::after {
  transition:
    opacity 420ms ease,
    transform 420ms ease;
}

.tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
  opacity: 0.55;
  transform: translateY(10px);
}

.tybow-spec-line {
  --pin-line-delay: 0ms;
}

.tybow-spec-line::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 1px;
  background: var(--border);
}

@media (prefers-reduced-motion: no-preference) {
  .tybow-spec .tybow-spec-line::after {
    transform: scaleX(0);
    transform-origin: left center;
    transition: transform 620ms cubic-bezier(0.23, 1, 0.32, 1)
      var(--pin-line-delay, 0ms);
  }

  .tybow-spec .tybow-spec-tick {
    opacity: 0;
    transform: translateX(-5px);
    transition:
      opacity 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--pin-line-delay, 0ms),
      transform 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--pin-line-delay, 0ms);
  }

  .tybow-spec.is-inview .tybow-spec-line::after {
    transform: scaleX(1);
  }

  .tybow-spec.is-inview .tybow-spec-tick {
    opacity: 1;
    transform: none;
  }

  .tybow-spec-line:nth-child(1) {
    --pin-line-delay: 300ms;
  }
  .tybow-spec-line:nth-child(2) {
    --pin-line-delay: 375ms;
  }
  .tybow-spec-line:nth-child(3) {
    --pin-line-delay: 450ms;
  }
  .tybow-spec-line:nth-child(4) {
    --pin-line-delay: 525ms;
  }
  .tybow-spec-line:nth-child(5) {
    --pin-line-delay: 600ms;
  }
  .tybow-spec-line:nth-child(6) {
    --pin-line-delay: 675ms;
  }
}

@media (max-width: 800px) {
  .tybow-gallery {
    height: auto;
    min-height: 0;
    flex-direction: column;
  }

  .tybow-gallery-item {
    flex: 0 0 2.65rem;
    width: 100%;
    min-width: 0;
    height: 2.65rem;
    transition:
      height 0.4s cubic-bezier(0.22, 1, 0.36, 1),
      flex-basis 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .tybow-gallery-item.is-active {
    flex: 0 0 22rem;
    height: 22rem;
  }

  .tybow-gallery-item::after {
    background: linear-gradient(
      to top,
      color-mix(in oklch, var(--foreground) 88%, transparent) 0%,
      color-mix(in oklch, var(--foreground) 45%, transparent) 70%,
      transparent 100%
    );
  }

  .tybow-gallery-spine {
    writing-mode: horizontal-tb;
    transform: none;
    inset: auto auto 0.7rem 0.9rem;
    padding: 0;
    font-size: 0.78rem;
    letter-spacing: 0.16em;
  }
}

@media (max-width: 959px) {
  .tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tybow-pull,
  .tybow-pull-late {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .tybow-hero-slide,
  .tybow-hero-slide.is-on,
  .tybow-look-slide,
  .tybow-overview-slide,
  .tybow-gallery-item,
  .tybow-gallery-item::after,
  .tybow-gallery-spine,
  .tybow-gallery-cap,
  .tybow-deck-card-body,
  .tybow-deck-card::after {
    transition: none;
    transform: none;
  }

  .tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
    opacity: 1;
    transform: none;
  }
}
